SELECT e.*
FROM ts_agent_chat_message_event e
INNER JOIN ts_agent_chat_session s ON s.id = e.session_id
INNER JOIN ts_agent_chat_message m ON m.id = e.message_id
  AND m.session_id = e.session_id
WHERE s.user_id = #{userId}
  AND s.is_deleted = 0
  AND s.session_status != 'deleted'
  AND m.is_deleted = 0
  AND e.is_deleted = 0

    AND e.session_id = #{sessionId}


    AND e.message_id = #{messageId}


    AND e.type = #{type}


    AND e.name = #{name}


    AND e.node_name = #{nodeName}


    AND e.status = #{status}

ORDER BY e.created_at DESC, e.id DESC

SELECT e.* FROM ts_agent_chat_message_event e INNER JOIN ts_agent_chat_session s ON s.id = e.session_id INNER JOIN ts_agent_chat_message m ON m.id = e.message_id AND m.session_id = e.session_id WHERE s.user_id = #{userId} AND s.is_deleted = 0 AND s.session_status != 'deleted' AND m.is_deleted = 0 AND e.is_deleted = 0 AND e.session_id = #{sessionId} AND e.message_id IN
#{messageId}
ORDER BY e.message_id ASC, e.created_at ASC, e.id ASC
